41	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
42	const FIXED_SUBJECT: &str = "CN=example.com";
43	const FIXED_ISSUER: &str = "CN=Test CA";
44	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
45	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
46	
47	// ----- Algorithm OID arcs --------------------------------------------------
48	
49	const RSA_ENCRYPTION: &[u64] = &[1, 2, 840, 113549, 1, 1, 1];
50	const EC_PUBLIC_KEY: &[u64] = &[1, 2, 840, 10045, 2, 1];
51	const P256_CURVE: &[u64] = &[1, 2, 840, 10045, 3, 1, 7];
52	
53	// ----- Success: AlgorithmIdentifier parameter forms ------------------------
54	
55	#[test]
56	fn spki_without_parameters_is_accepted() {
57	    // The parameters element is OPTIONAL: an AlgorithmIdentifier carrying
58	    // only the OID must be accepted exactly like one with an explicit NULL.
59	    let spki = spki_of(&alg_with_oid_only(RSA_ENCRYPTION), &default_key());
60	    let (out, _cert) = run_inspect("params-absent", &build_cert(&spki));
61	    assert_success(&out);
62	}
63	
64	#[test]
65	fn spki_with_explicit_null_parameters_is_accepted() {
66	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &default_key());
67	    let (out, _cert) = run_inspect("params-null", &build_cert(&spki));
68	    assert_success(&out);
69	}
70	
71	#[test]
72	fn spki_with_other_single_complete_parameter_value_is_accepted() {
73	    // Parameters need not be NULL: any one complete DER TLV is read and
74	    // accepted without being interpreted. An INTEGER parameter is one such
75	    // value; an embedded OID (the namedCurve form used by EC keys) is another.
76	    let integer_params = tlv(0x02, &[0x01, 0x00]); // INTEGER 0
77	    let spki = spki_of(
78	        &alg_with(RSA_ENCRYPTION, &integer_params),
79	        &default_key(),
80	    );
81	    let (out, _cert) = run_inspect("params-integer", &build_cert(&spki));
82	    assert_success(&out);
83	
84	    let oid_params = oid(P256_CURVE);
85	    let spki = spki_of(&alg_with(EC_PUBLIC_KEY, &oid_params), &default_key());
86	    let (out, _cert) = run_inspect("params-oid", &build_cert(&spki));
87	    assert_success(&out);
88	}
89	
90	#[test]
91	fn spki_with_unknown_but_decodable_algorithm_oid_is_accepted() {
92	    // The tool does not recognize 1.2.3.4 or 1.2.840.99999.7 as key
93	    // algorithms, but recognition is irrelevant: an OID that decodes by the
94	    // normal base-128 rules (99999 needs a multi-byte arc) is accepted, both
95	    // with and without parameters.
96	    let spki = spki_of(
97	        &alg_with_null_params(&[1, 2, 3, 4]),
98	        &default_key(),
99	    );
100	    let (out, _cert) = run_inspect("unknown-oid-null", &build_cert(&spki));
101	    assert_success(&out);
102	
103	    let spki = spki_of(
104	        &alg_with_oid_only(&[1, 2, 840, 99999, 7]),
105	        &default_key(),
106	    );
107	    let (out, _cert) = run_inspect("unknown-oid-longarc", &build_cert(&spki));
108	    assert_success(&out);
109	}
110	
111	// ----- Success: BIT STRING unused-bits encoding ----------------------------
112	
113	#[test]
114	fn public_key_with_zero_unused_bits_and_data_is_accepted() {
115	    // Zero unused bits over several data bytes, including a final 0xFF byte
116	    // whose low bits are all significant: nothing about the payload content
117	    // is judged (it need not be a real RSA/EC key DER).
118	    let key = bit_string(&[0x00, 0xAA, 0x55, 0xFF, 0x00]);
119	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &key);
120	    let (out, _cert) = run_inspect("bits-zero", &build_cert(&spki));
121	    assert_success(&out);
122	}
123	
124	#[test]
125	fn public_key_with_nonzero_unused_bits_and_clear_low_bits_is_accepted() {
126	    // Unused counts 1, 3 and 7 all succeed as long as the corresponding low
127	    // bits of the final data byte are zero. These encodings are checked; the
128	    // data itself is never required to be a usable public key.
129	    let cases: &[&[u8]] = &[
130	        &[0x01, 0x02], // 1 unused bit;  last byte low 1 bit  = 0
131	        &[0x03, 0xF8], // 3 unused bits; last byte low 3 bits = 000
132	        &[0x07, 0x80], // 7 unused bits; last byte low 7 bits = 0000000
133	    ];
134	    for (i, content) in cases.iter().enumerate() {
135	        let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(content));
136	        let (out, _cert) = run_inspect(&format!("bits-nonzero-{i}"), &build_cert(&spki));
137	        assert_success(&out);
138	    }
139	}
140	
141	#[test]
142	fn public_key_empty_bit_string_with_zero_count_is_accepted() {
143	    // Existing behavior, pinned deliberately: a BIT STRING holding only the
144	    // zero unused-bits count (no data at all) is accepted. The check covers
145	    // encoding well-formedness, not whether a cryptographically usable key
146	    // exists.
147	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(&[0x00]));
148	    let (out, _cert) = run_inspect("bits-empty", &build_cert(&spki));
149	    assert_success(&out);
150	}
151	
152	// ----- Failure: SubjectPublicKeyInfo structure -----------------------------
153	
154	#[test]
155	fn spki_missing_algorithm_identifier_is_rejected() {
156	    // The BIT STRING on its own, with no leading AlgorithmIdentifier
157	    // SEQUENCE, must not be skipped even though the key bytes are present.
158	    let spki = seq(&default_key());
159	    let (out, _cert) = run_inspect("spki-no-alg", &build_cert(&spki));
160	    assert_invalid_certificate(&out);
161	}
162	
163	#[test]
164	fn spki_missing_public_key_bit_string_is_rejected() {
165	    let spki = seq(&alg_with_null_params(RSA_ENCRYPTION));
166	    let (out, _cert) = run_inspect("spki-no-key", &build_cert(&spki));
167	    assert_invalid_certificate(&out);
168	}
169	
170	#[test]
171	fn spki_algorithm_identifier_with_wrong_tag_is_rejected() {
172	    // A bare OID in the AlgorithmIdentifier position is the wrong element
173	    // type: the identifier must itself be a SEQUENCE.
174	    let spki = seq(&concat(&[&oid(RSA_ENCRYPTION), &default_key()]));
175	    let (out, _cert) = run_inspect("spki-alg-tag", &build_cert(&spki));
176	    assert_invalid_certificate(&out);
177	}
178	
179	#[test]
180	fn spki_public_key_with_wrong_tag_is_rejected() {
181	    // An OCTET STRING where the subjectPublicKey BIT STRING must stand is a
182	    // type error, not a key that merely cannot be interpreted.
183	    let wrong_key = tlv(0x04, &[0x00, 0x01, 0x00]);
184	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &wrong_key);
185	    let (out, _cert) = run_inspect("spki-key-tag", &build_cert(&spki));
186	    assert_invalid_certificate(&out);
187	}
188	
189	#[test]
190	fn spki_with_extra_element_after_bit_string_is_rejected() {
191	    // Exactly two elements belong in SubjectPublicKeyInfo; a third TLV after
192	    // the key (here an INTEGER) makes the certificate corrupt.
193	    let extra = tlv(0x02, &[0x01, 0x2A]);
194	    let spki = seq(&concat(&[
195	        &alg_with_null_params(RSA_ENCRYPTION),
196	        &default_key(),
197	        &extra,
198	    ]));
199	    let (out, _cert) = run_inspect("spki-trailing", &build_cert(&spki));
200	    assert_invalid_certificate(&out);
201	}
202	
203	// ----- Failure: AlgorithmIdentifier contents -------------------------------
204	
205	#[test]
206	fn algorithm_identifier_missing_oid_is_rejected() {
207	    // An empty AlgorithmIdentifier SEQUENCE has no algorithm OID at all.
208	    let alg = seq(&[]);
209	    let spki = spki_of(&alg, &default_key());
210	    let (out, _cert) = run_inspect("alg-no-oid", &build_cert(&spki));
211	    assert_invalid_certificate(&out);
212	}
213	
214	#[test]
215	fn algorithm_oid_with_truncated_encoding_is_rejected() {
216	    // A single continuation byte 0x88 with no terminating byte promises
217	    // another base-128 byte that never arrives. The enclosing SEQUENCEs are
218	    // correctly sized, so the truncation is detected inside the OID itself.
219	    let truncated_oid = raw_tlv(0x06, &[0x01], &[0x88]);
220	    let alg = seq(&truncated_oid);
221	    let spki = spki_of(&alg, &default_key());
222	    let (out, _cert) = run_inspect("alg-oid-trunc", &build_cert(&spki));
223	    assert_invalid_certificate(&out);
224	}
225	
226	#[test]
227	fn algorithm_oid_with_nonminimal_encoding_is_rejected() {
228	    // Arc value 1 encoded as 0x80 0x01 (leading 0x80 continuation byte) is
229	    // not the shortest possible base-128 encoding and is invalid DER.
230	    let nonminimal_oid = raw_tlv(0x06, &[0x02], &[0x80, 0x01]);
231	    let alg = seq(&nonminimal_oid);
232	    let spki = spki_of(&alg, &default_key());
233	    let (out, _cert) = run_inspect("alg-oid-nonmin", &build_cert(&spki));
234	    assert_invalid_certificate(&out);
235	}
236	
237	#[test]
238	fn algorithm_parameter_with_truncated_value_is_rejected() {
239	    // The parameter TLV announces five content bytes but only three follow;
240	    // a half-read parameter cannot be salvaged by ignoring its tail.
241	    let truncated_params = raw_tlv(0x04, &[0x05], b"abc");
242	    let alg = seq(&concat(&[&oid(RSA_ENCRYPTION), &truncated_params]));
243	    let spki = spki_of(&alg, &default_key());
244	    let (out, _cert) = run_inspect("alg-params-trunc", &build_cert(&spki));
245	    assert_invalid_certificate(&out);
246	}
247	
248	#[test]
249	fn algorithm_identifier_with_multiple_parameters_is_rejected() {
250	    // Parameters are one OPTIONAL element, never a sequence of them: a NULL
251	    // followed by a second TLV must be rejected.
252	    let null_params = tlv(0x05, &[]);
253	    let second = tlv(0x02, &[0x01, 0x00]);
254	    let alg = seq(&concat(&[&oid(RSA_ENCRYPTION), &null_params, &second]));
255	    let spki = spki_of(&alg, &default_key());
256	    let (out, _cert) = run_inspect("alg-params-multi", &build_cert(&spki));
257	    assert_invalid_certificate(&out);
258	}
259	
260	// ----- Failure: subjectPublicKey BIT STRING contents -----------------------
261	
262	#[test]
263	fn public_key_bit_string_without_unused_bits_byte_is_rejected() {
264	    // A zero-length BIT STRING content has no leading unused-bits count at
265	    // all (contrast with [0x00], the empty-but-counted form that is accepted).
266	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(&[]));
267	    let (out, _cert) = run_inspect("bits-no-count", &build_cert(&spki));
268	    assert_invalid_certificate(&out);
269	}
270	
271	#[test]
272	fn public_key_bit_string_with_unused_count_above_seven_is_rejected() {
273	    // The count is three bits wide; 8 cannot name unused bits in a byte.
274	    let spki = spki_of(
275	        &alg_with_null_params(RSA_ENCRYPTION),
276	        &bit_string(&[0x08, 0x00]),
277	    );
278	    let (out, _cert) = run_inspect("bits-count-8", &build_cert(&spki));
279	    assert_invalid_certificate(&out);
280	}
281	
282	#[test]
283	fn public_key_bit_string_nonzero_count_without_data_is_rejected() {
284	    // Declaring unused bits requires at least the byte they are unused in:
285	    // a lone nonzero count names bits that cannot exist.
286	    for (i, count) in [0x01u8, 0x07].into_iter().enumerate() {
287	        let spki = spki_of(
288	            &alg_with_null_params(RSA_ENCRYPTION),
289	            &bit_string(&[count]),
290	        );
291	        let (out, _cert) = run_inspect(&format!("bits-nodata-{i}"), &build_cert(&spki));
292	        assert_invalid_certificate(&out);
293	    }
294	}
295	
296	#[test]
297	fn public_key_bit_string_with_set_unused_tail_bits_is_rejected() {
298	    // With a nonzero count the named low bits of the final data byte must be
299	    // zero. Each case below has at least one of them set, so the encoding
300	    // lies about its padding even though the rest of the certificate parses.
301	    let cases: &[&[u8]] = &[
302	        &[0x01, 0x01], // 1 unused bit;  low 1 bit set
303	        &[0x02, 0x03], // 2 unused bits; both low bits set
304	        &[0x03, 0xF9], // 3 unused bits; lowest of them set (...001)
305	        &[0x07, 0x81], // 7 unused bits; lowest bit set
306	        &[0x03, 0x00, 0x01], // padding is judged on the FINAL byte only,
307	                             // and that final byte still has a set low bit
308	    ];
309	    for (i, content) in cases.iter().enumerate() {
310	        let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(content));
311	        let (out, _cert) = run_inspect(&format!("bits-tailset-{i}"), &build_cert(&spki));
312	        assert_invalid_certificate(&out);
313	    }
314	}
315	
316	// ----- Assertions / process plumbing --------------------------------------
317	
318	/// A successful inspect must print exactly the five fixed fields in their
319	/// fixed order; none of their content varies with the SPKI encoding, and
320	/// stderr stays empty.
321	fn assert_success(out: &Output) {
322	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
323	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
324	    assert_eq!(
325	        lossy(&out.stdout),
326	        format!(
327	            "Subject: {FIXED_SUBJECT}\n\
328	             Issuer: {FIXED_ISSUER}\n\
329	             Serial Number: {FIXED_SERIAL}\n\
330	             Not Before: {FIXED_NOT_BEFORE}\n\
331	             Not After: {FIXED_NOT_AFTER}\n"
332	        )
333	    );
334	}
335	
336	/// Every malformed-input case shares the documented contract: exit code 2,
337	/// nothing at all on stdout (parse failure precedes every print), and the
338	/// fixed invalid-certificate prefix on stderr with a non-empty reason after
339	/// it. The reason's exact wording is intentionally not pinned.
340	fn assert_invalid_certificate(out: &Output) {
341	    assert_eq!(
342	        out.status.code(),
343	        Some(2),
344	        "stdout={} stderr={}",
345	        lossy(&out.stdout),
346	        lossy(&out.stderr)
347	    );
348	    assert!(
349	        out.stdout.is_empty(),
350	        "stdout must be empty on failure, got: {}",
351	        lossy(&out.stdout)
352	    );
353	    let stderr = lossy(&out.stderr);
354	    assert!(
355	        stderr.starts_with("chainview: invalid DER certificate: "),
356	        "unexpected stderr: {stderr}"
357	    );
358	    assert!(
359	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
360	        "missing error reason in stderr: {stderr}"
361	    );
362	}
363	
364	fn lossy(bytes: &[u8]) -> String {
365	    String::from_utf8_lossy(bytes).into_owned()
366	}
367	
368	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
369	    let cert = TempCert::new(tag, data);
370	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
371	        .arg("inspect")
372	        .arg(&cert.path)
373	        .output()
374	        .expect("running chainview");
375	    (output, cert)
376	}
377	
378	struct TempCert {
379	    path: PathBuf,
380	}
381	
382	impl TempCert {
383	    fn new(tag: &str, data: &[u8]) -> Self {
384	        static COUNTER: AtomicU64 = AtomicU64::new(0);
385	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
386	        let path = std::env::temp_dir().join(format!(
387	            "chainview-spki-test-{}-{tag}-{unique}.der",
388	            std::process::id()
389	        ));
390	        fs::write(&path, data).expect("writing temp certificate");
391	        TempCert { path }
392	    }
393	}
394	
395	impl Drop for TempCert {
396	    fn drop(&mut self) {
397	        let _ = fs::remove_file(&self.path);
398	    }
399	}
400	
401	// ----- Certificate / DER construction -------------------------------------
402	//
403	// Only the structural pieces needed here. Lengths are always emitted in the
404	// minimal DER form, except where a test injects hand-written length or
405	// content bytes (truncated or non-minimal OID arcs, a truncated parameter);
406	// such bytes are always wrapped by correctly sized SEQUENCEs so rejection is
407	// proven to come from the element under test.
408	
409	/// Assemble a complete, parseable v1 DER certificate with fixed names,
410	/// serial, validity and signature material around the supplied
411	/// SubjectPublicKeyInfo TLV.
412	fn build_cert(spki: &[u8]) -> Vec<u8> {
413	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
414	    let validity = seq(&concat(&[
415	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
416	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
417	    ]));
418	    let subject = simple_cn_name("example.com");
419	    let issuer = simple_cn_name("Test CA");
420	
421	    let tbs = seq(&concat(&[
422	        &serial,
423	        &signature_algorithm(),
424	        &issuer,
425	        &validity,
426	        &subject,
427	        spki,
428	    ]));
429	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
430	}
431	
432	fn signature_algorithm() -> Vec<u8> {
433	    // sha256WithRSAEncryption with explicit NULL parameters.
434	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
435	}
436	
437	/// SubjectPublicKeyInfo ::= SEQUENCE { algorithm AlgorithmIdentifier,
438	/// subjectPublicKey BIT STRING }.
439	fn spki_of(alg: &[u8], key: &[u8]) -> Vec<u8> {
440	    seq(&concat(&[alg, key]))
441	}
442	
443	fn alg_with_oid_only(arcs: &[u64]) -> Vec<u8> {
444	    seq(&oid(arcs))
445	}
446	
447	fn alg_with_null_params(arcs: &[u64]) -> Vec<u8> {
448	    alg_with(arcs, &tlv(0x05, &[]))
449	}
450	
451	/// AlgorithmIdentifier with one caller-supplied complete parameter TLV.
452	fn alg_with(arcs: &[u64], params: &[u8]) -> Vec<u8> {
453	    seq(&concat(&[&oid(arcs), params]))
454	}
455	
456	/// BIT STRING carrying the supplied content (unused-bits count plus data).
457	fn bit_string(content: &[u8]) -> Vec<u8> {
458	    tlv(0x03, content)
459	}
460	
461	/// A small, well-formed key BIT STRING: zero unused bits, two data bytes.
462	fn default_key() -> Vec<u8> {
463	    bit_string(&[0x00, 0x01, 0x00])
464	}
465	
466	fn simple_cn_name(cn: &str) -> Vec<u8> {
467	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
468	    let rdn = tlv(0x31, &atv); // SET { CN=... }
469	    tlv(0x30, &rdn) // SEQUENCE { RDN }
470	}
471	
472	/// TLV with caller-supplied length bytes; used to forge truncated encodings.
473	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
474	    let mut out = vec![tag];
475	    out.extend_from_slice(len_bytes);
476	    out.extend_from_slice(content);
477	    out
478	}
479	
480	fn oid(arcs: &[u64]) -> Vec<u8> {
481	    assert!(arcs.len() >= 2);
482	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
483	    for &arc in &arcs[2..] {
484	        content.extend_from_slice(&oid_arc(arc));
485	    }
486	    tlv(0x06, &content)
487	}
488	
489	fn oid_arc(mut value: u64) -> Vec<u8> {
490	    let mut out = vec![(value % 128) as u8];
491	    value /= 128;
492	    while value > 0 {
493	        out.push(0x80 | (value % 128) as u8);
494	        value /= 128;
495	    }
496	    out.reverse();
497	    out
498	}
499	
500	fn seq(content: &[u8]) -> Vec<u8> {
501	    tlv(0x30, content)
502	}
503	
504	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
505	    let mut out = vec![tag];
506	    out.extend_from_slice(&der_len(content.len()));
507	    out.extend_from_slice(content);
508	    out
509	}
510	
511	fn der_len(n: usize) -> Vec<u8> {
512	    if n < 0x80 {
513	        vec![n as u8]
514	    } else {
515	        let mut body = Vec::new();
516	        let mut v = n;
517	        while v > 0 {
518	            body.push((v & 0xFF) as u8);
519	            v >>= 8;
520	        }
521	        body.reverse();
522	        let mut out = vec![0x80 | body.len() as u8];
523	        out.extend_from_slice(&body);
524	        out
525	    }
526	}
527	
528	fn concat(parts: &[&[u8]]) -> Vec<u8> {
529	    let mut out = Vec::new();
530	    for part in parts {
531	        out.extend_from_slice(part);
532	    }
533	    out
534	}
