1	//! End-to-end regression tests for checking the two signature algorithm
2	//! descriptions when running `chainview inspect <DER-FILE>`.
3	//!
4	//! A certificate carries the signature algorithm twice:
5	//!
6	//! ```text
7	//! Certificate ::= SEQUENCE {
8	//!     tbsCertificate      TBSCertificate,
9	//!     signatureAlgorithm  AlgorithmIdentifier,   -- outer copy
10	//!     signatureValue      BIT STRING }
11	//! TBSCertificate ::= SEQUENCE {
12	//!     ...,
13	//!     signature           AlgorithmIdentifier,   -- copy to be signed
14	//!     ... }
15	//! ```
16	//!
17	//! Both copies must be complete, well-formed AlgorithmIdentifiers and must
18	//! agree exactly (same algorithm OID and the same parameter representation;
19	//! an absent parameter and an explicit NULL differ). Damage to either copy,
20	//! or any disagreement between the two healthy copies, must reject the whole
21	//! certificate with the usual malformed-input contract even though Subject,
22	//! Issuer, serial and validity all remain readable. The check is purely
23	//! about encoding and internal consistency: the signature itself is never
24	//! verified and trust is never judged, unknown but decodable OIDs are
25	//! accepted, and the signature OID need not match the subjectPublicKey
26	//! algorithm OID.
27	//!
28	//! Every case drives the real `chainview` binary: success prints exactly the
29	//! five fixed fields with exit code 0 and empty stderr; failure yields exit
30	//! code 2, completely empty stdout and a
31	//! `chainview: invalid DER certificate: <reason>` stderr whose reason names
32	//! whether the outer copy, the copy inside tbsCertificate, or their
33	//! disagreement caused the rejection.
34	
35	use std::fs;
36	use std::path::PathBuf;
37	use std::process::{Command, Output};
38	use std::sync::atomic::{AtomicU64, Ordering};
39	
40	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
41	const FIXED_SUBJECT: &str = "CN=example.com";
42	const FIXED_ISSUER: &str = "CN=Test CA";
43	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
44	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
45	
46	// ----- Algorithm OID arcs --------------------------------------------------
47	
48	const SHA256_WITH_RSA: &[u64] = &[1, 2, 840, 113549, 1, 1, 11];
49	const RSA_ENCRYPTION: &[u64] = &[1, 2, 840, 113549, 1, 1, 1];
50	const ECDSA_WITH_SHA256: &[u64] = &[1, 2, 840, 10045, 4, 3, 2];
51	
52	// ----- Success: both copies agree ------------------------------------------
53	
54	#[test]
55	fn matching_algorithms_with_null_parameters_are_accepted() {
56	    // The standard sha256WithRSAEncryption form: OID plus an explicit NULL
57	    // in both copies.
58	    let alg = alg_with_null_params(SHA256_WITH_RSA);
59	    let (out, _cert) = run_inspect("match-null", &build_cert(&alg, &alg));
60	    assert_success(&out);
61	}
62	
63	#[test]
64	fn matching_algorithms_without_parameters_are_accepted() {
65	    // Parameters are OPTIONAL; both copies omitting them entirely is fine
66	    // (ECDSA algorithm identifiers are commonly encoded this way).
67	    let alg = alg_with_oid_only(ECDSA_WITH_SHA256);
68	    let (out, _cert) = run_inspect("match-absent", &build_cert(&alg, &alg));
69	    assert_success(&out);
70	}
71	
72	#[test]
73	fn matching_algorithms_with_identical_non_null_parameters_are_accepted() {
74	    // The parameter need not be NULL: any single complete DER value is
75	    // accepted without interpretation, as long as both copies carry the very
76	    // same TLV. An INTEGER parameter and an OID parameter both qualify.
77	    let integer = tlv(0x02, &[0x01, 0x2A]);
78	    let alg = alg_with(SHA256_WITH_RSA, &integer);
79	    let (out, _cert) = run_inspect("match-int", &build_cert(&alg, &alg));
80	    assert_success(&out);
81	
82	    let oid_param = oid(&[1, 2, 840, 10045, 3, 1, 7]);
83	    let alg = alg_with(&[1, 2, 3, 4], &oid_param);
84	    let (out, _cert) = run_inspect("match-oid-param", &build_cert(&alg, &alg));
85	    assert_success(&out);
86	}
87	
88	#[test]
89	fn unknown_but_decodable_algorithm_oid_is_accepted() {
