```rust
/// Why an AlgorithmIdentifier's content failed the shared structural check.
/// Every variant carries the raw facts; each reader turns them into its own
/// established error wording.
enum AlgIdError {
    /// The leading OID element could not be read as a TLV at all.
    OidRead(String),
    /// The first element is present but is not an OID.
    OidTag(u8),
    /// The OID element exists but its content is not a valid OID.
    OidContent(String),
    /// A parameter element follows the OID but cannot be read as one
    /// complete TLV.
    ParamsRead(String),
    /// Bytes remain after the parameter element: more than one parameter.
    ExtraAfterParams,
}

/// Split the content of an AlgorithmIdentifier SEQUENCE into its algorithm
/// OID and optional parameters, enforcing the structure every reader shares:
/// exactly one leading OID (complete and shortest-encoded), then either
/// nothing or exactly one complete DER parameter value, and nothing after
/// that. The parameter TLV is returned as its full original encoding (tag,
/// length and content) so callers that compare two identifiers can do so at
/// the byte level; the parameter content itself is never interpreted.
fn split_algorithm_identifier(content: &[u8]) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
    let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
    if oid.tag != TAG_OID {
        return Err(AlgIdError::OidTag(oid.tag));
    }
    parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
    let params = if rest.is_empty() {
        None
    } else {
        let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
        if !after.is_empty() {
            return Err(AlgIdError::ExtraAfterParams);
        }
        Some(&rest[..rest.len() - after.len()])
    };
    Ok((oid, params))
}
